INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfc4e70dd5b944e6aa97489ccdc694e25f795d09/content/books/zizhi-tongjian/vol-288/year-0948/part-07/sources/library/jiuwudaishi-101-september-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002459；EPUB电子本，纸本及异文待核", "id": "5f26c87b-679f-5879-8b67-80f2884633f1"}, {"title": "宋史·巻二百五十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfc4e70dd5b944e6aa97489ccdc694e25f795d09/content/books/zizhi-tongjian/vol-288/year-0948/part-07/sources/library/songshi-254-hou-yanguang-nurse/source.txt", "note": "《宋史》巻二百五十四，段落 songshi-9c6e46fee832-p057458；EPUB电子本，纸本及异文待核", "id": "d688250a-4aed-5fd4-a1c1-ddeca80e45a3"}, {"title": "资治通鉴·后汉纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfc4e70dd5b944e6aa97489ccdc694e25f795d09/content/books/zizhi-tongjian/vol-288/year-0948/part-07/sources/library/tongjian-288-948-september-october/source.txt", "note": "《资治通鉴》后汉纪三，段落 zizhi-tongjian-a63549944a71-p003419；电子底本待考，分段待核", "id": "5dd92625-5b82-53e2-a934-748b7c57b05d"}, {"title": "新五代史·卷六十五", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfc4e70dd5b944e6aa97489ccdc694e25f795d09/content/books/zizhi-tongjian/vol-288/year-0948/part-07/sources/library/xinwudaishi-065-zhong-chu-marriage/source.txt", "note": "《新五代史》卷六十五，段落 xin-wudaishi-b08f244b9241-p003285；EPUB电子本，纸本及异文待核", "id": "c857bdf7-d3fa-58c9-963a-32af5b69b1bd"}, {"title": "新五代史·卷六十六", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfc4e70dd5b944e6aa97489ccdc694e25f795d09/content/books/zizhi-tongjian/vol-288/year-0948/part-07/sources/library/xinwudaishi-066-ma-separate-tribute/source.txt", "note": "《新五代史》卷六十六，段落 xin-wudaishi-b08f244b9241-p003328；EPUB电子本，纸本及异文待核", "id": "40edad7d-6a3a-5de8-85c1-532cb3e5549e"}, {"title": "资治通鉴·后汉纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4f57a30a26d134a760f4628c87dbbe735d6f3c2/content/books/zizhi-tongjian/vol-288/year-0948/part-06/sources/library/tongjian-288-948-august-september/source.txt", "note": "《资治通鉴》后汉纪三，段落 zizhi-tongjian-a63549944a71-p003418；电子底本待考，分段待核", "id": "59171fec-2ee4-563c-bfb5-8250bc322756"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4f57a30a26d134a760f4628c87dbbe735d6f3c2/content/books/zizhi-tongjian/vol-288/year-0948/part-06/sources/library/jiuwudaishi-101-august-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002458；EPUB电子本，纸本及异文待核", "id": "e3020a52-b8f3-532c-aa8d-f2572696bc9b"}, {"title": "新五代史·卷十一", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4f57a30a26d134a760f4628c87dbbe735d6f3c2/content/books/zizhi-tongjian/vol-288/year-0948/part-06/sources/library/xinwudaishi-011-guo-rewards/source.txt", "note": "《新五代史》卷十一，段落 xin-wudaishi-b08f244b9241-p000362；EPUB电子本，纸本及异文待核", "id": "44daf767-2198-5790-9d76-d57b75bf536c"}, {"title": "新五代史·卷六十四", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5047247441ba8ca5148602bf0116a6c308eb295b/content/books/zizhi-tongjian/vol-288/year-0948/part-05/sources/library/xinwudaishi-064-zhang-ye-fall/source.txt", "note": "《新五代史》卷六十四，段落 xin-wudaishi-b08f244b9241-p003239；EPUB电子本，纸本及异文待核", "id": "3f1464f7-a574-5fd7-89e5-a4a073e0999b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}, {"name": "常思", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉昭义节度使。948年讨伐李守贞等三镇时曾驻潼关，后来与郭威、白文珂、刘词分三路进攻河中。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "1d3a1e89-5826-52d4-ba66-55dbc3d91e22"}, {"name": "赵思绾", "aliases": ["趙思綰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州人，原在赵在礼军中，后来成为赵匡赞牙将。948年王景崇试图令赵匡赞牙兵刺面防逃时，主动提出先刺自己以率众。齐藏珍建议将其杀死，王景崇不听。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b571162d-9596-5439-a443-f33cd87ea628"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "王处回", "aliases": ["王處回"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王处回，为税官请免的中门副使。", "biography": null, "status": "draft", "id": "159fd2b3-759b-522a-a971-11356c6fe970"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "钟允章", "aliases": ["鍾允章"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉知制诰。948年奉刘晟之命到楚国求婚，马希广拒绝；返回后向刘晟说明马氏兄弟正在相争。《新五代史》还记他的工部郎中职务。婚姻双方未具名，生卒年未据本次原文确定。", "biography": null, "status": "draft", "id": "e31bf81a-3c5e-51e7-87a1-0c580cdea1e7"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "欧弘练（楚天策府内都押牙）", "aliases": ["歐弘練（楚天策府內都押牙）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "948年任楚国天策府内都押牙，与进奏官张仲荀建议马希广向后汉执政者送重礼，阻止马希萼单独朝贡求官。与943年所见客将区弘练存在姓字差异，是否同人，尚待校核；生卒年未载。", "biography": null, "status": "draft", "id": "a36a973b-bcaf-5e3e-b082-854486d516d1"}, {"name": "张仲荀", "aliases": ["張仲荀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国进奏官。948年与天策府内都押牙欧弘练共同出谋，马希广据其建议向后汉执政者送重礼，使朝廷拒绝马希萼单独朝贡求官的请求。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "b18a30a7-b24f-5fcd-bffc-37a59900b523"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "赵晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：赵晖。", "biography": null, "status": "draft", "id": "9efd6fe6-4ba6-5e2b-99cc-751822d75039"}, {"name": "李彦从", "aliases": ["李彥從"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任左飞龙使，恒州驱逐契丹驻军后，奉刘知远命率军前往增援。生卒年未载。", "biography": null, "status": "draft", "id": "36337a5b-3293-5487-ba5b-47ef5d6636d5"}, {"name": "张业", "aliases": ["張業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张业。", "biography": null, "status": "draft", "id": "79f0f8ee-f0c7-5ba0-a428-aacf648664be"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "王守筠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "侯益部下。948年九月戊申从凤翔逃来，报告侯益家属被王景崇杀害，《旧五代史》本纪记载这次报告。生卒年未载。", "biography": null, "status": "draft", "id": "7b91e2e8-678f-5fd7-a15b-04a2e6ce21e1"}, {"name": "侯仁矩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "侯益之子，曾任天平行军司马。王景崇杀侯益家属时，他先前已在外，因此幸免；948年九月庚申任隰州刺史。其子侯延广当时还在襁褓中，由乳母刘氏救出。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "61e742c6-279c-535a-b777-43993dace74a"}, {"name": "侯延广", "aliases": ["侯延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "侯仁矩之子、侯益之孙。948年侯益家属遭王景崇杀害时尚在襁褓，乳母刘氏用自己的孩子替换他，抱他逃走，一路乞食到大梁，送回侯益家。具体出生年未据年龄反推，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ed14b630-313d-5f9d-9681-f721381ea172"}, {"name": "刘氏（侯延广乳母）", "aliases": ["劉氏（侯延廣乳母）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "侯延广的乳母，只有刘姓而未记名字。侯益家属遭王景崇杀害时，她用自己的孩子替换侯延广，抱侯延广逃到大梁送回侯益家。《宋史》补记她的孩子代侯延广遇害。生卒年未载。", "biography": null, "status": "draft", "id": "dd09a89e-5141-5288-8c0a-1f2200bb4548"}, {"name": "刘氏的孩子（侯延广乳母所生）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "侯延广乳母刘氏所生的孩子，姓名、年龄及性别未明确记载。刘氏在侯益家属遭杀时，用这个孩子替换侯延广；《宋史》明确记载其代侯延广遇害。", "biography": null, "status": "draft", "id": "e3f55203-6457-5004-8601-8bc28b24882f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李守贞指望旧部因往日恩惠而迎接他", "start_year": null, "end_year": null, "time_original": "郭威军抵河中前的追述，形成这一判断的具体年月未载", "dynasty": "五代十国", "description": "李守贞认为禁军曾在自己麾下、受过恩惠，又不满后汉严法，因此指望他们到来时开城奉迎，自己可以坐等。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a5eed20f-60e5-5c42-aa52-94a7ccd24958"}, {"title": "士卒接受郭威赏赐，不再顾念李守贞的旧恩", "start_year": 948, "end_year": 948, "time_original": "948年八月抵河中城下前后，具体日未载", "dynasty": "五代十国", "description": "士卒接受郭威赏赐，不再顾念李守贞的旧恩。", "phases": [], "location_name": "郭威军中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "540f6c67-3c8b-567f-bb15-212d764f3dfb"}, {"title": "郭威军抵达河中城下，鼓噪示威，李守贞失色", "start_year": 948, "end_year": 948, "time_original": "948年八月己亥；《旧五代史》奏报说二十三日抵城，日期差异保留", "dynasty": "五代十国", "description": "郭威军抵达河中城下，鼓噪示威，李守贞失色。", "phases": [], "location_name": "河中城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "90286f87-34d1-5823-ba1d-d08129afdae1"}, {"title": "白文珂攻克河中西关城", "start_year": 948, "end_year": 948, "time_original": "948年八月抵城以后，具体日未载", "dynasty": "五代十国", "description": "白文珂攻克河中西关城。", "phases": [], "location_name": "河中西关城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "278b27ce-60bc-5b0d-af73-15b496292f02"}, {"title": "白文珂、常思和郭威在河中周围设营", "start_year": 948,