SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李守贞认为禁军曾在自己麾下、受过恩惠，又不满后汉严法，因此指望他们到来时开城奉迎，自己可以坐等。", "citation": "卷288·乾祐元年（948年八月至九月及追述）·zztj-v288-y0948-p043·原文件第49行", "note": "原文：始，李守贞以禁军皆尝在麾下，受其恩施，又士卒素骄，苦汉法之严，谓其至则叩城奉迎，可坐而待之。；核对说明：这是史书记载的李守贞判断，不当成士卒已经作出迎接承诺或城已打开。", "status": "draft", "id": "23bd1616-4340-5302-a3a8-5d455a67eca7", "subject_id": "a5eed20f-60e5-5c42-aa52-94a7ccd24958", "source_id": "59171fec-2ee4-563c-bfb5-8250bc322756"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "郭威军抵河中前的追述，形成这一判断的具体年月未载", "citation": "卷288·乾祐元年（948年八月至九月及追述）·zztj-v288-y0948-p043·原文件第49行", "note": "原文：始，李守贞以禁军皆尝在麾下，受其恩施，又士卒素骄，苦汉法之严，谓其至则叩城奉迎，可坐而待之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c46ade95-3619-58cd-ac14-3541e2a81c73", "subject_id": "a5eed20f-60e5-5c42-aa52-94a7ccd24958", "source_id": "59171fec-2ee4-563c-bfb5-8250bc322756"}, {"subject_table": "person", "field_path": "description", "claim_text": "李守贞：以禁军旧部曾受恩为由，期待他们主动迎接。", "citation": "卷288·乾祐元年（948年八月至九月及追述）·zztj-v288-y0948-p043·原文件第49行", "note": "原文：始，李守贞以禁军皆尝在麾下，受其恩施，又士卒素骄，苦汉法之严，谓其至则叩城奉迎，可坐而待之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "782c2e4c-c2e8-5038-91e1-b71af64d7c1c", "subject_id": "a3d16959-684f-5c82-b848-8dcbdc73e85a", "source_id": "59171fec-2ee4-563c-bfb5-8250bc322756"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李守贞：以禁军旧部曾受恩为由，期待他们主动迎接。", "citation": "卷288·乾祐元年（948年八月至九月及追述）·zztj-v288-y0948-p043·原文件第49行", "note": "原文：始，李守贞以禁军皆尝在麾下，受其恩施，又士卒素骄，苦汉法之严，谓其至则叩城奉迎，可坐而待之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "d4fc250f-92b1-5415-a540-4b3d354668f7", "subject_id": "c4b03324-2923-5304-ab66-f4711687ef68", "source_id": "59171fec-2ee4-563c-bfb5-8250bc322756"}, {"subject_table": "event", "field_path": "description", "claim_text": "士卒接受